func requireStatus2xx(t *testing.T, operation string, response runtimeResponse, err error) runtimeResponse {
	t.Helper()
	if err != nil { t.Fatalf("%s transport: %v", operation, err) }
	if response.Status/100 != 2 { t.Fatalf("%s status=%d body=%s", operation, response.Status, strings.TrimSpace(string(response.Body))) }
	return response
}

func decodeAny(t *testing.T, body []byte) any {
	t.Helper()
	var decoded any
	if err := json.Unmarshal(body, &decoded); err != nil { t.Fatalf("decode JSON: %v body=%s", err, string(body)) }
	return decoded
}

func findStringByKey(value any, key string) string {
	switch typed := value.(type) {
	case map[string]any:
		if found, ok := typed[key].(string); ok && found != "" { return found }
		for _, child := range typed { if found := findStringByKey(child, key); found != "" { return found } }
	case []any:
		for _, child := range typed { if found := findStringByKey(child, key); found != "" { return found } }
	}
	return ""
}

func actionKey(t *testing.T, client runtimeClient, objectKey, expected string) string {
	t.Helper()
	response := requireStatus2xx(t, "action catalog", client.request(t.Context(), http.MethodGet, "/records/"+url.PathEscape(objectKey)+"/actions", nil, runtimeRequestOptions{}))
	var walk func(any) bool
	walk = func(value any) bool {
		switch typed := value.(type) {
		case map[string]any:
			if key, ok := typed["key"].(string); ok && key == expected { return true }
			for _, child := range typed { if walk(child) { return true } }
		case []any:
			for _, child := range typed { if walk(child) { return true } }
		}
		return false
	}
	if !walk(decodeAny(t, response.Body)) { t.Fatalf("action catalog for %s missing exact key %s", objectKey, expected) }
	return expected
}

func recordByField(t *testing.T, client runtimeClient, objectKey, field string, expected any) recordEnvelope {
	t.Helper()
	page, err := client.listRecords(t.Context(), objectKey, 1, 200)
	if err != nil { t.Fatalf("list %s: %v", objectKey, err) }
	for _, item := range page.Items { if fmt.Sprint(item.Data[field]) == fmt.Sprint(expected) { return item } }
	t.Fatalf("%s record with %s=%v not found in %d items", objectKey, field, expected, len(page.Items))
	return recordEnvelope{}
}

func detailRecord(t *testing.T, client runtimeClient, objectKey, recordID string) recordEnvelope {
	t.Helper()
	response := requireStatus2xx(t, "record detail", client.request(t.Context(), http.MethodGet, "/records/"+url.PathEscape(objectKey)+"/items/"+url.PathEscape(recordID), nil, runtimeRequestOptions{}))
	var item recordEnvelope
	if err := json.Unmarshal(response.Body, &item); err != nil { t.Fatalf("decode detail: %v", err) }
	if item.ID != recordID { t.Fatalf("detail identity mismatch got=%q want=%q", item.ID, recordID) }
	return item
}

func provisionDepartment(t *testing.T, admin runtimeClient, code, name string) string {
	t.Helper()
	key := actionKey(t, admin, "department_anchor", "department_anchor.provision")
	response, err := admin.runObjectAction(t.Context(), "department_anchor", key, map[string]any{"department_code": code, "department_name": name}, "department-"+code)
	requireStatus2xx(t, "provision department", response, err)
	anchor := recordByField(t, admin, "department_anchor", "department_code", code)
	if anchor.OwnerOrg == "" { t.Fatalf("department %s missing Runtime organization ownership", code) }
	return anchor.OwnerOrg
}

func deliverActor(t *testing.T, admin runtimeClient, flow, suffix, roleKey, orgID string, managerID *string) testActor {
	t.Helper()
	key := actionKey(t, admin, "sales_profile", "sales_profile.deliver_identity")
	employeeCode := strings.ToUpper(flow+"-"+suffix)
