func runWorkflow(t *testing.T, client runtimeClient, workflowKey, idempotency string, body map[string]any) string {
	t.Helper()
	response := requireStatus2xx(t, "run workflow", client.request(t.Context(), http.MethodPost, "/workflow/definitions/"+url.PathEscape(workflowKey)+"/run", body, runtimeRequestOptions{IdempotencyKey: idempotency}))
	decoded := decodeAny(t, response.Body)
	processID := findStringByKey(decoded, "process_id")
	if processID == "" { processID = findStringByKey(decoded, "id") }
	if processID == "" { t.Fatalf("workflow response missing process id: %s", string(response.Body)) }
	return processID
}

func pendingTask(t *testing.T, client runtimeClient, processID string) workflowTask {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		response := requireStatus2xx(t, "list workflow tasks", client.request(t.Context(), http.MethodGet, "/workflow/tasks?status=pending&limit=100", nil, runtimeRequestOptions{}))
		tasks, err := decodeWorkflowTasks(response.Body)
		if err != nil { t.Fatalf("decode tasks: %v", err) }
		for _, task := range tasks { if task.ProcessID == processID { return task } }
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("pending task for process %s not found", processID)
	return workflowTask{}
}

func waitProcessTerminal(t *testing.T, client runtimeClient, processID string) map[string]any {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		response := requireStatus2xx(t, "workflow process detail", client.request(t.Context(), http.MethodGet, "/workflow/processes/"+url.PathEscape(processID), nil, runtimeRequestOptions{}))
		var decoded map[string]any
		if err := json.Unmarshal(response.Body, &decoded); err != nil { t.Fatalf("decode process: %v", err) }
		status := strings.ToLower(fmt.Sprint(decoded["status"]))
		if status == "completed" || status == "approved" || status == "rejected" { return decoded }
		if status == "failed" || status == "cancelled" { t.Fatalf("workflow process terminal failure: %v", decoded) }
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("workflow process %s did not reach terminal state", processID)
	return nil
}

func inboxItems(t *testing.T, client runtimeClient) []map[string]any {
	t.Helper()
	response := requireStatus2xx(t, "notification inbox", client.request(t.Context(), http.MethodGet, "/notification/inbox?limit=100", nil, runtimeRequestOptions{}))
	var page struct { Items []map[string]any `json:"items"` }
	if err := json.Unmarshal(response.Body, &page); err != nil { t.Fatalf("decode inbox: %v", err) }
	return page.Items
}

func notificationsFor(items []map[string]any, eventType, subjectID string) []map[string]any {
	result := make([]map[string]any, 0)
	for _, item := range items {
		if fmt.Sprint(item["event_type"]) == eventType && (subjectID == "" || fmt.Sprint(item["subject_id"]) == subjectID) { result = append(result, item) }
	}
	return result
}

