func cents(value string) (*big.Rat, bool) { result, ok := new(big.Rat).SetString(value); return result, ok }

func expectedFunnel(t *testing.T, items []recordEnvelope) map[string]struct{ count int; amount *big.Rat } {
	t.Helper()
	result := map[string]struct{ count int; amount *big.Rat }{}
	for _, item := range items {
		status := fmt.Sprint(item.Data["status"])
		amount, ok := cents(fmt.Sprint(item.Data["estimated_amount"])); if !ok { t.Fatalf("invalid amount: %v", item.Data["estimated_amount"]) }
		current := result[status]
		if current.amount == nil { current.amount = new(big.Rat) }
		current.count++
		current.amount = new(big.Rat).Add(current.amount, amount)
		result[status] = current
	}
	return result
}

func TestBF07DirectorFunnelReport(t *testing.T) {
	phase := managedPhase(t)
	_, east, _, director, north := setupSalesTeam(t, "bf07", false, true)
	newLead := createLead(t, east, "BF07 新线索", "10.00", "website", "bf07-new")
	contacted := createLead(t, east, "BF07 已跟进", "20.00", "event", "bf07-contacted")
	runLeadAction(t, east, contacted.ID, "lead.mark_contacted", "bf07-contacted-step", map[string]any{"status": "contacted"})
	qualified := qualifyLead(t, east, createLead(t, east, "BF07 合格", "30.00", "referral", "bf07-qualified"), "bf07-qualified")
	lost := qualifyLead(t, *north, createLead(t, *north, "BF07 丢失", "40.00", "outbound", "bf07-lost"), "bf07-lost")
	runLeadAction(t, *north, lost.ID, "lead.mark_lost", "bf07-lost-step", map[string]any{"status": "lost"})
	converted := qualifyLead(t, east, createLead(t, east, "BF07 已转化", "50.00", "website", "bf07-converted"), "bf07-converted")
	runLeadAction(t, east, converted.ID, "lead.convert_direct", "bf07-convert-step", map[string]any{})
	_ = newLead
	_ = qualified
	all, err := director.Client.listRecords(t.Context(), "lead", 1, 200); if err != nil { t.Fatal(err) }
	expected := expectedFunnel(t, all.Items)
	report := requireStatus2xx(t, "query funnel", director.Client.request(t.Context(), http.MethodPost, "/report/lead_funnel/query", map[string]any{"page_size": 100}, runtimeRequestOptions{}))
	var decoded struct { Rows []struct { Dimensions map[string]string `json:"dimensions"`; Measures map[string]string `json:"measures"` } `json:"rows"` }
	if err := json.Unmarshal(report.Body, &decoded); err != nil { t.Fatal(err) }
	seen := map[string]bool{}
	for _, row := range decoded.Rows {
		status := row.Dimensions["status"]
		want, ok := expected[status]; if !ok { t.Fatalf("unexpected report status %q", status) }
		count, err := strconv.Atoi(row.Measures["lead_count"]); if err != nil { t.Fatal(err) }
		amount, ok := cents(row.Measures["estimated_amount_total"]); if !ok { t.Fatalf("invalid report amount %q", row.Measures["estimated_amount_total"]) }
		if count != want.count || amount.Cmp(want.amount) != 0 { t.Fatalf("funnel mismatch %s got=%d/%s want=%d/%s", status, count, amount.RatString(), want.count, want.amount.RatString()) }
		seen[status] = true
	}
	if len(seen) != len(expected) { t.Fatalf("funnel groups got=%d want=%d", len(seen), len(expected)) }
	denied, err := east.Client.request(t.Context(), http.MethodPost, "/report/lead_funnel/query", map[string]any{"page_size": 100}, runtimeRequestOptions{}); if err != nil { t.Fatal(err) }
	if denied.Status != http.StatusForbidden { t.Fatalf("sales funnel status=%d", denied.Status) }
	emitEvidence(t, phase, "BF07", passedStep("bf07-report", "lead.funnel_report.reconciled", "runtime.report", []string{"15"}, map[string]any{"durable_result_read_back": true, "status_group_count": len(seen), "counts_and_decimal_sums_reconciled": true, "sales_access_denied": true}))
}

func createExportAudit(t *testing.T, director testActor) recordEnvelope {
	t.Helper()
	scopeHash := "bf08-scope"
	response := requireStatus2xx(t, "create export audit", director.Client.request(t.Context(), http.MethodPost, "/records/report_export_audit", map[string]any{"data": map[string]any{"report_key": "lead_detail_export", "requested_by": director.UserID, "status": "requested", "row_count": 0, "scope_hash": scopeHash}}, runtimeRequestOptions{IdempotencyKey: "bf08-audit"}))

	response := requireStatus2xx(t, "create export audit", director.Client.request(t.Context(), http.MethodPost, "/records/report_export_audit", map[string]any{"data": map[string]any{"report_key": "lead_detail_export", "requested_by": director.UserID, "status": "requested", "row_count": 0, "scope_hash": scopeHash}}, runtimeRequestOptions{IdempotencyKey: "bf08-audit"}))
	var item recordEnvelope
	if err := json.Unmarshal(response.Body, &item); err == nil && item.ID != "" { return item }
	return recordByField(t, director.Client, "report_export_audit", "scope_hash", scopeHash)
}

func reportRowCount(t *testing.T, client runtimeClient, key string) int {
	t.Helper()
	response := requireStatus2xx(t, "query export report", client.request(t.Context(), http.MethodPost, "/report/"+url.PathEscape(key)+"/query", map[string]any{"page_size": 200}, runtimeRequestOptions{}))
	var decoded map[string]any
	if err := json.Unmarshal(response.Body, &decoded); err != nil { t.Fatal(err) }
	value, ok := decoded["row_count"].(float64); if !ok { t.Fatalf("report row_count missing: %v", decoded) }
	return int(value)
}

func waitExportJob(t *testing.T, client runtimeClient, jobID string) map[string]any {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		response := requireStatus2xx(t, "get export job", client.request(t.Context(), http.MethodGet, "/data-exchange/jobs/"+url.PathEscape(jobID)+"?provider=reports&operation=export", nil, runtimeRequestOptions{}))
		var job map[string]any
		if err := json.Unmarshal(response.Body, &job); err != nil { t.Fatal(err) }
		status := fmt.Sprint(job["status"])
		if status == "completed" { return job }
		if status == "failed" || status == "cancelled" { t.Fatalf("export job failed: %v", job) }
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("export job %s did not complete", jobID)
	return nil
}

func TestBF08GovernedRequesterOwnedCSVExport(t *testing.T) {
	phase := managedPhase(t)
	_, rep, _, director, _ := setupSalesTeam(t, "bf08", false, false)
	createLead(t, rep, "BF08 导出线索", "88000.00", "event", "bf08")
	reportRows := reportRowCount(t, director.Client, "lead_detail_export")
	audit := createExportAudit(t, director)
	scope := map[string]any{"purpose": "销售漏斗管理复盘", "freshness": map[string]any{"mode": "realtime"}}
	preparePath := "/report/lead_detail_export/exports/lead/prepare"
	prepare := requireStatus2xx(t, "prepare report export", director.Client.request(t.Context(), http.MethodPost, preparePath, map[string]any{"audit_id": audit.ID, "scope": scope}, runtimeRequestOptions{IdempotencyKey: "report.exports.prepare:bf08", OperationReason: "销售总监导出有界线索明细用于管理复盘", OperationConfirmation: "confirmed"}))
	jobID := findStringByKey(decodeAny(t, prepare.Body), "id")
	if jobID == "" { t.Fatalf("prepare missing job id") }
	deniedPrepare, err := rep.Client.request(t.Context(), http.MethodPost, preparePath, map[string]any{"audit_id": audit.ID, "scope": scope}, runtimeRequestOptions{IdempotencyKey: "report.exports.prepare:bf08-denied", OperationReason: "越权导出探测", OperationConfirmation: "confirmed"}); if err != nil { t.Fatal(err) }
	if deniedPrepare.Status != http.StatusForbidden { t.Fatalf("sales prepare status=%d body=%s", deniedPrepare.Status, string(deniedPrepare.Body)) }
	job := waitExportJob(t, director.Client, jobID)
	foreignGet, err := rep.Client.request(t.Context(), http.MethodGet, "/data-exchange/jobs/"+url.PathEscape(jobID)+"?provider=reports&operation=export", nil, runtimeRequestOptions{}); if err != nil { t.Fatal(err) }
	if foreignGet.Status/100 == 2 { t.Fatalf("foreign actor can read export job") }
	download := requireStatus2xx(t, "download export", director.Client.request(t.Context(), http.MethodGet, "/data-exchange/jobs/"+url.PathEscape(jobID)+"/download?provider=reports&operation=export", nil, runtimeRequestOptions{}))
	foreignDownload, err := rep.Client.request(t.Context(), http.MethodGet, "/data-exchange/jobs/"+url.PathEscape(jobID)+"/download?provider=reports&operation=export", nil, runtimeRequestOptions{}); if err != nil { t.Fatal(err) }
	if foreignDownload.Status/100 == 2 { t.Fatalf("foreign actor downloaded export") }
	records, err := csv.NewReader(bytes.NewReader(download.Body)).ReadAll(); if err != nil { t.Fatalf("parse CSV: %v", err) }
	if len(records) == 0 || len(records)-1 != reportRows { t.Fatalf("CSV rows=%d report=%d", len(records)-1, reportRows) }
	sum := sha256.Sum256(download.Body)
	actualHash := hex.EncodeToString(sum[:])
	expectedHash := fmt.Sprint(job["content_sha256"])
	if expectedHash == "" || expectedHash == "<nil>" || !strings.EqualFold(expectedHash, actualHash) { t.Fatalf("content hash mismatch got=%s want=%s", actualHash, expectedHash) }
	contentType := download.Header.Get("Content-Type")
	if !strings.Contains(strings.ToLower(contentType), "text/csv") { t.Fatalf("content type=%q", contentType) }
	steps := []evidenceStep{
		passedStep("bf08-prepare", "report.prepare", "runtime.report", []string{"16"}, map[string]any{"accepted": true, "job_id": jobID}),
		passedStep("bf08-prepare-denied", "report.prepare.unauthorized_denied", "runtime.report", []string{"16"}, map[string]any{"access_denied": true, "different_actor": true, "job_id": jobID}),
		passedStep("bf08-owner", "data_exchange.job.owner_bound", "runtime.data_exchange", []string{"16"}, map[string]any{"requester_owned": true, "job_id": jobID}),
		passedStep("bf08-completed", "data_exchange.job.completed", "runtime.data_exchange", []string{"16"}, map[string]any{"job_id": jobID, "job_status": "completed"}),
		passedStep("bf08-download", "data_exchange.job.download", "runtime.data_exchange", []string{"16"}, map[string]any{"job_id": jobID, "actual_job_download": true, "byte_count": len(download.Body), "content_type": contentType}),
		passedStep("bf08-foreign", "data_exchange.job.foreign_download_denied", "runtime.data_exchange", []string{"16"}, map[string]any{"access_denied": true, "different_actor": true, "job_id": jobID}),
		passedStep("bf08-content", "artifact.csv.content_validated", "runtime.data_exchange", []string{"16"}, map[string]any{"csv_parsed": true, "row_count_matches_report": true, "content_hash_verified": true}),
	}
	sort.SliceStable(steps, func(i, j int) bool { return i < j })
	emitEvidence(t, phase, "BF08", steps...)
}

